// 0 = missad, 1 = klar, 2 = vilodag (a rest day keeps the chain).
// 85 slots ending Mon 2026-07-27 (index 84 = today).
function lcg(seed){ let s=seed>>>0; return ()=> (s=(s*1664525+1013904223)>>>0)/4294967296; }

function build({seed,streak,doneToday,p,pRest,rests=[],best}){
  const r=lcg(seed);
  const a=Array.from({length:85},()=> r()<p ? (r()<pRest?"2":"1") : "0");
  const last = doneToday ? 84 : 83;                 // last day the streak covers
  if(!doneToday) a[84]="0";                         // today not acted on yet
  for(let i=last;i>last-streak;i--) a[i]="1";
  a[last-streak]="0";                               // the miss that capped it
  for(const i of rests) a[i]="2";                   // rest days inside the run
  if(best){ const [start,len]=best;
    for(let i=start;i<start+len;i++) a[i]="1";
    a[start-1]="0"; a[start+len]="0"; }
  return a.join("");
}

// streak = consecutive days without a miss, ending at `last`
function streakOf(h,doneToday){
  let n=0; for(let i=(doneToday?84:83); i>=0 && h[i]!=="0"; i--) n++;
  return n;
}
function longestRun(h,upto){                        // ignore the pending today slot
  let best=0,run=0;
  for(let i=0;i<=upto;i++){ if(h[i]!=="0"){run++; best=Math.max(best,run);} else run=0; }
  return best;
}

const specs=[
  {id:"traning",    seed:11, streak:12, doneToday:false, p:0.62, pRest:0.18, rests:[82], best:[30,24]},
  {id:"lasa",       seed:23, streak:5,  doneToday:false, p:0.70, pRest:0.12},
  {id:"vatten",     seed:31, streak:8,  doneToday:false, p:0.66, pRest:0.10},
  {id:"meditation", seed:47, streak:32, doneToday:true,  p:0.72, pRest:0.14},
  {id:"spanska",    seed:59, streak:46, doneToday:true,  p:0.78, pRest:0.10},
];

const out={};
for(const s of specs){
  const h=build(s);
  const upto = s.doneToday?84:83;
  const rec={history:h, streak:streakOf(h,s.doneToday), windowLongest:longestRun(h,upto)};
  out[s.id]=rec;
  const ok = rec.streak===s.streak ? "ok" : "MISMATCH want "+s.streak;
  console.log(s.id.padEnd(11), "streak", String(rec.streak).padStart(2), "| longest i fonstret", String(rec.windowLongest).padStart(2), "|", ok);
}
console.log();
// today across all habits, for the Monday ring: 2 of 5
console.log("klara idag:", specs.filter(s=>s.doneToday).length, "av", specs.length);
for(const s of specs) console.log(s.id.padEnd(11), out[s.id].history);
require("fs").writeFileSync("/tmp/streak-history.json", JSON.stringify(out,null,2));
'

